import os
import numpy as np

# ==========================================
# Directories and Paths
# ==========================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
IMAGES_DIR = os.path.join(INPUT_DIR, "images")

# Working directory for caching intermediate results specific to this idea
WORKING_DIR = "./working/idea_61"
os.makedirs(WORKING_DIR, exist_ok=True)

# Submission directory
SUBMISSION_DIR = "./submission"
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# Metadata File Paths (Generated by metadata script)
TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

# Sample Submission Path
SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

# Final Submission Output Path
SUBMISSION_FILE_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# ==========================================
# Caching Configuration
# ==========================================
# Paths for caching the initial feature extraction (Tabular + Geometric/Geodesic)
CACHE_TRAIN_FEATURES = os.path.join(WORKING_DIR, "train_features.parquet")
CACHE_VAL_FEATURES = os.path.join(WORKING_DIR, "val_features.parquet")
CACHE_TEST_FEATURES = os.path.join(WORKING_DIR, "test_features.parquet")

# Paths for caching the finalized, preprocessed arrays (Sanitized -> Transformed -> Scaled)
CACHE_X_TRAIN = os.path.join(WORKING_DIR, "X_train.npy")
CACHE_Y_TRAIN = os.path.join(WORKING_DIR, "y_train.npy")
CACHE_X_VAL = os.path.join(WORKING_DIR, "X_val.npy")
CACHE_Y_VAL = os.path.join(WORKING_DIR, "y_val.npy")
CACHE_X_TEST = os.path.join(WORKING_DIR, "X_test.npy")
CACHE_TEST_IDS = os.path.join(WORKING_DIR, "test_ids.npy")
CACHE_CLASSES = os.path.join(WORKING_DIR, "classes.npy")

# ==========================================
# Global Settings
# ==========================================
RANDOM_SEED = 42
DEBUG_MODE = False  # Set to True to limit dataset size for rapid debugging

# ==========================================
# Data Processing Configuration
# ==========================================
# Column Names
ID_COL = "id"
TARGET_COL = "species"
FILE_PATH_COL = "file_path"

# Feature Groups
# The original 192 features are implicit in the CSV, but we define the new extracted ones
GEOMETRIC_FEATURES = [
    "area",
    "eccentricity",
    "solidity",
    "extent",
    "aspect_ratio",
]

# Numerical Precision
# Enforce float64 to prevent numerical instability in matrix inversion (OAS) and log-loss calculation
FLOAT_PRECISION = np.float64

# ==========================================
# Preprocessing Pipeline Hyperparameters
# ==========================================
# 1. Sanitization: Variance Threshold
# Removes constant features (variance = 0) to prevent scaler explosion
VARIANCE_THRESHOLD = 0.0

# 2. Transformation: Yeo-Johnson
# Stabilizes variance and makes data more Gaussian-like
USE_YEO_JOHNSON = True

# 3. Scaling: Standard Scaler
# Centers data around 0 with unit variance
USE_STANDARD_SCALING = True

# ==========================================
# Model Hyperparameters (OAS-LDA)
# ==========================================
# Oracle Approximating Shrinkage settings
# assume_centered=True because we center data via StandardScaler (with mean subtraction)
OAS_ASSUME_CENTERED = True
